#include <vector>
#include <algorithm>

class Solution {
    long long power(long long base, long long exp) {
        long long res = 1, MOD = 1000000007;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }
public:
    int numberOfWays(int n, int x, int y) {
        long long MOD = 1000000007;
        int max_j = std::min(n, x);

        std::vector<std::vector<long long>> dp(n + 1, std::vector<long long>(max_j + 1, 0));
        dp[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= std::min(i, max_j); ++j) {
                dp[i][j] = (dp[i - 1][j - 1] + (long long)j * dp[i - 1][j]) % MOD;
            }
        }

        long long total = 0, perm = 1;
        for (int j = 1; j <= max_j; ++j) {
            perm = (perm * (x - j + 1)) % MOD;
            long long ways = (dp[n][j] * perm) % MOD;
            ways = (ways * power(y, j)) % MOD;
            total = (total + ways) % MOD;
        }
        return total;
    }
};

class Solution {
    private final int MOD = 1_000_000_007;

    public int numberOfWays(int n, int x, int y) {
        int maxJ = Math.min(n, x);
        long[][] dp = new long[n + 1][maxJ + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= Math.min(i, maxJ); j++) {
                dp[i][j] = (dp[i - 1][j - 1] + (long) j * dp[i - 1][j]) % MOD;
            }
        }

        long total = 0, perm = 1;
        for (int j = 1; j <= maxJ; j++) {
            perm = (perm * (x - j + 1)) % MOD;
            long ways = (dp[n][j] * perm) % MOD;
            ways = (ways * power(y, j)) % MOD;
            total = (total + ways) % MOD;
        }
        return (int) total;
    }

    private long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

var numberOfWays = function(n, x, y) {
    const MOD = 1000000007n;
    const maxJ = Math.min(n, x);

    function power(base, exp) {
        let res = 1n;
        let b = BigInt(base) % MOD;
        let e = BigInt(exp);
        while (e > 0n) {
            if (e & 1n) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1n;
        }
        return res;
    }

    const dp = Array.from({ length: n + 1 }, () => new BigInt64Array(maxJ + 1));
    dp[0][0] = 1n;

    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= Math.min(i, maxJ); j++) {
            dp[i][j] = (dp[i - 1][j - 1] + BigInt(j) * dp[i - 1][j]) % MOD;
        }
    }

    let total = 0n, perm = 1n;
    const bigX = BigInt(x);

    for (let j = 1; j <= maxJ; j++) {
        perm = (perm * (bigX - BigInt(j - 1))) % MOD;
        let ways = (dp[n][j] * perm) % MOD;
        ways = (ways * power(y, j)) % MOD;
        total = (total + ways) % MOD;
    }
    return Number(total);
};
